import{_ as t,l as i,o as e,c as l,v as o,p as s,x as n,d,i as h,S as u}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"统一理解与生成 Janus / Show-o","description":"","frontmatter":{"title":"统一理解与生成 Janus / Show-o","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/unified-understanding-generation.md","filePath":"llm/unified-understanding-generation.md","lastUpdated":1789023840000}'),E={name:"llm/unified-understanding-generation.md"};function m(p,a,c,A,f,_){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="统一理解与生成-janus-show-o" tabindex="-1">统一理解与生成 Janus / Show-o <a class="header-anchor" href="#统一理解与生成-janus-show-o" aria-label="Permalink to &quot;统一理解与生成 Janus / Show-o&quot;">​</a></h1><div class="epigraph"><p>同一套语言模型权重既要谈图又要造图。视觉编码器若为理解优化，量化码就伤 OCR；若为码本优化，谈图又变盲。</p><footer>—— Wu 等 Janus（解耦视觉编码）；Xie 等 Show-o；对照 Chameleon 的统一离散 token</footer></div><p><a href="/llm/mar-masked-ar">上一课</a>表明生成可以走连续。<a href="/llm/continuous-vs-discrete-vision-tokens">连续对离散</a> 已把轴钉死。缺口是产品形态：一个模型、两套任务。Janus 拆视觉编码；Show-o 在一个 Transformer 里混自回归与离散扩散。后课 Transfusion 用「下一步 + 扩散」写进同一前向。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理解要 <a href="/llm/clip">CLIP</a> / SigLIP 式连续 patch + <a href="/llm/llava-projector">LLaVA 投影器</a>，好绑定与 OCR。生成若用同一连续向量，没有 softmax 词表；若共用 VQ 编码器，理解掉细节。强行单编码器是零和。Janus 的回答是解耦：理解走连续视觉塔，生成走离散塔，语言骨干共享。Show-o 把理解当 AR 文本（含连续或离散视觉），生成用掩码离散扩散，仍一张网。</p><p>Chameleon 把图文都离散化进同一词表，接口干净，理解侧付量化税。</p><p><span class="marginnote">「统一」要声明统一的是权重、词表，还是训练混合。只把两个专家接在一个聊天入口，不是本课的统一模型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选接口：双塔（Janus）、混合目标单塔（Show-o / 后课 Transfusion）、全离散词表（Chameleon）。训练必须两任务混合，否则共享 LLM 会被一方洗掉。评测分列：POPE / VQA 与 FID / 文生图，禁止用单一「全能分」。视觉前端理解侧仍应是 <a href="/llm/vit-as-encoder">ViT</a> 连续特征。</p>',9)),(e(),s(u,null,{default:n(()=>[h(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PIX%5B%22%E5%83%8F%E7%B4%A0%22%5D%20--%3E%20UND%5B%22%E7%90%86%E8%A7%A3%E7%BC%96%E7%A0%81%E5%99%A8%20%E8%BF%9E%E7%BB%AD%22%5D%0A%20%20PIX%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E7%BC%96%E7%A0%81%E5%99%A8%20%E7%A6%BB%E6%95%A3%E6%88%96%E6%8E%A9%E7%A0%81%22%5D%0A%20%20UND%20--%3E%20LLM%5B%22%E5%85%B1%E4%BA%AB%20LLM%22%5D%0A%20%20GEN%20--%3E%20LLM%0A%20%20LLM%20--%3E%20TXT%5B%22%E6%96%87%E6%9C%AC%22%5D%0A%20%20LLM%20--%3E%20IMG%5B%22%E5%9B%BE%E5%83%8F%E7%A0%81%E6%88%96%E6%89%A9%E6%95%A3%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>解耦让梯度不再穿越同一视觉瓶颈：理解损失更新连续塔，生成损失更新码塔，LLM 学两套前缀语法。代价是参数与协议双份，以及「图既当输入又当输出」时两塔要对齐语义。单塔混合则靠目标加权，避免一种损失主导。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>双塔不是端到端世界模型。下一课把文本 CE 与图像扩散写进同一次 Transformer 计算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>统一模型必须显式处理理解连续与生成离散的冲突。</li><li>Janus 解耦编码器；Show-o 混合 AR 与掩码扩散。</li><li>评测必须分列理解和生成。</li><li>出处：Janus；Show-o；Chameleon。</li></ul>',6))])}const S=t(E,[["render",m]]);export{T as __pageData,S as default};
